/** Federal share of the combined rate, by country. Everything else is regional. */
const FEDERAL_RATES: Record<string, number> = { CA: 0.05 };

/**
 * The federal and regional parts (fractions) of the rate for `taxClass` at `address`.
 * They add up to `taxRateFor`; without a specific entry everything is regional.
